ZivonSim.register("b-04", {
  init: function (ctx) { ctx.t0 = 4; },
  draw: function (ctx) {
    var g = ctx.g;
    for (var t = 0; t <= 6; t += 0.1) {
      var x = 0.08 * t * t * t;
      if (t === 0) g.moveTo(t * 60, 280 - x * 10);
      else g.lineTo(t * 60, 280 - x * 10);
    }
    var readEl = ctx.canvas && ctx.canvas.parentElement && ctx.canvas.parentElement.querySelector(".zn-sim-read");
    if (readEl) readEl.textContent = "t = 4.0 s, x = 5.12 m, v = 3.84 m/s";
  }
});
ZivonSim.register("b-08", {
  init: function (ctx) { ctx.v0 = 5; ctx.a = 2; },
  draw: function (ctx) {
    var g = ctx.g;
    for (var t = 0; t <= 4; t += 0.1) {
      var v = 5 + 2 * t;
      if (t === 0) g.moveTo(t * 80, 260 - v * 6);
      else g.lineTo(t * 80, 260 - v * 6);
    }
    var readEl = ctx.canvas && ctx.canvas.parentElement && ctx.canvas.parentElement.querySelector(".zn-sim-read");
    if (readEl) readEl.textContent = "t = 2.0 s, v = 9.0 m/s, displacement = 14.0 m";
  }
});

